// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.interaction.MutableInteractionSourceimport androidx.compose.foundation.interaction.collectIsPressedAsStateimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.rememberimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.scaleimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.theme.LocalAuroraBrush/** * NeoButton — primary call-to-action button with aurora gradient fill. * * - Pressed state: scales to 0.96 (tactile feedback) * - Disabled state: 50% opacity * - Optional leading icon * * @param text button label * @param onClick click handler * @param modifier layout modifier * @param icon optional leading icon * @param enabled when false, button is disabled */@Composablefun NeoButton(    text: String,    onClick: () -> Unit,    modifier: Modifier = Modifier,    icon: ImageVector? = null,    enabled: Boolean = true,) {    val interactionSource = remember { MutableInteractionSource() }    val isPressed by interactionSource.collectIsPressedAsState()    val scale = if (isPressed) 0.96f else 1f    val alpha = if (enabled) 1f else 0.5f    val brush = LocalAuroraBrush.current    Row(        modifier = modifier            .scale(scale)            .background(                brush = brush,                shape = RoundedCornerShape(16.dp),            )            .clickable(                interactionSource = interactionSource,                indication = null,                enabled = enabled,                onClick = onClick,            )            .padding(PaddingValues(horizontal = 20.dp, vertical = 14.dp)),        verticalAlignment = Alignment.CenterVertically,    ) {        if (icon != null) {            Icon(                imageVector = icon,                contentDescription = null,                tint = androidx.compose.ui.graphics.Color.White,                modifier = Modifier.size(18.dp),            )            Spacer(modifier = Modifier.size(8.dp))        }        Text(            text = text,            style = MaterialTheme.typography.labelLarge,            color = androidx.compose.ui.graphics.Color.White.copy(alpha = alpha),        )    }}/** * TactileButton — secondary button with surface background + aurora border. * Used for "Cancel", "Skip", secondary actions. */@Composablefun TactileButton(    text: String,    onClick: () -> Unit,    modifier: Modifier = Modifier,    icon: ImageVector? = null,    enabled: Boolean = true,) {    val interactionSource = remember { MutableInteractionSource() }    val isPressed by interactionSource.collectIsPressedAsState()    val scale = if (isPressed) 0.97f else 1f    val alpha = if (enabled) 1f else 0.4f    Row(        modifier = modifier            .scale(scale)            .background(                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),                shape = RoundedCornerShape(16.dp),            )            .clickable(                interactionSource = interactionSource,                indication = null,                enabled = enabled,                onClick = onClick,            )            .padding(PaddingValues(horizontal = 20.dp, vertical = 14.dp)),        verticalAlignment = Alignment.CenterVertically,    ) {        if (icon != null) {            Icon(                imageVector = icon,                contentDescription = null,                tint = MaterialTheme.colorScheme.onSurface,                modifier = Modifier.size(18.dp),            )            Spacer(modifier = Modifier.size(8.dp))        }        Text(            text = text,            style = MaterialTheme.typography.labelLarge,            color = MaterialTheme.colorScheme.onSurface.copy(alpha = alpha),        )    }}/** * CircleIconButton — circular icon-only button (FAB-style, mic, attach, etc). */@Composablefun CircleIconButton(    icon: ImageVector,    contentDescription: String,    onClick: () -> Unit,    modifier: Modifier = Modifier,    size: androidx.compose.ui.unit.Dp = 48.dp,    gradient: Boolean = true,    enabled: Boolean = true,) {    val interactionSource = remember { MutableInteractionSource() }    val isPressed by interactionSource.collectIsPressedAsState()    val scale = if (isPressed) 0.92f else 1f    val alpha = if (enabled) 1f else 0.4f    val brush = LocalAuroraBrush.current    val backgroundModifier: Modifier = if (gradient) {        Modifier.background(brush = brush, shape = androidx.compose.foundation.shape.CircleShape)    } else {        Modifier.background(            color = MaterialTheme.colorScheme.surfaceVariant,            shape = androidx.compose.foundation.shape.CircleShape,        )    }    Box(        modifier = modifier            .size(size)            .scale(scale)            .then(backgroundModifier)            .clickable(                interactionSource = interactionSource,                indication = null,                enabled = enabled,                onClick = onClick,            ),        contentAlignment = Alignment.Center,    ) {        Icon(            imageVector = icon,            contentDescription = contentDescription,            tint = if (gradient) androidx.compose.ui.graphics.Color.White else MaterialTheme.colorScheme.onSurface,            modifier = Modifier.size(size * 0.5f),        )    }}